import { storeKinds, storeViews, storesScope, storeCatalogue, storeStock, reservationBag, storeReservations, storeMetrics, reservationStatuses, storeReports, storeReportTypes } from "./stores-data.js";
import { icon } from "./icons.js";
import { badge, button, emptyState, escapeHtml as e, pageHeading } from "./ui.js";

const statusTone = (status) => ["ready", "collected"].includes(status) ? "green" : status === "confirmed" ? "blue" : ["declined", "cancelled"].includes(status) ? "neutral" : "amber";
const footer = (label) => `<footer class="dialog-footer">${button("Cancel", "close-dialog", { variant: "secondary" })}<button type="submit" class="button primary">${label}</button></footer>`;
const choices = (entries, selected) => entries.map(([value, label]) => `<option value="${e(value)}" ${String(value) === String(selected) ? "selected" : ""}>${e(label)}</option>`).join("");
const error = '<p class="form-error" role="alert" hidden></p>';
const dateLabel = (at) => new Intl.DateTimeFormat("en-LK", { timeZone: "Asia/Colombo", day: "numeric", month: "short", year: "numeric" }).format(new Date(at));
const tabButton = (label, id, kind, selected) => button(label, "store-tab", { value: kind + "|" + id, variant: selected ? "primary" : "secondary", extra: `aria-pressed="${selected}"` });
const search = (f, kind) => `<label class="stores-search">${icon("search", 18)}<input type="search" data-change="store-query" data-kind="${kind}" data-focus="store-search" value="${e(f.query)}" placeholder="Search items, pupil or reference" aria-label="Search store records"></label>`;

function uniformArt(art) {
  const shape = art === "trousers" ? '<path d="M37 20h46l7 87H66L60 58l-6 49H30z"/><path d="M38 29h44M60 20v38"/>' : art === "skirt" ? '<path d="M42 23h36l20 83H22z"/><path d="M42 33h36M49 33l-9 73m20-73v73m11-73 9 73"/>' : '<path d="m43 24-22 14 12 24 11-7v52h36V55l11 7 12-24-22-14-10 9H53z"/><path d="m53 24 9 14 9-14M62 38v68M48 58h10v12H48z"/>';
  return `<div class="stores-uniform-art uniform-${e(art)}" aria-hidden="true"><svg viewBox="0 0 124 126">${shape}</svg><span>SUSSEX COLLEGE NETWORK</span></div>`;
}
function itemCard(state, item, kind) {
  const variants = item.variants.map((variant) => ({ ...variant, available: storeStock(state, item, variant).available })), available = variants.some((variant) => variant.available > 0);
  return `<article class="surface stores-item-card">${kind === "books" ? `<div class="cover-stage cover-${e(item.art)}"><div class="book-cover" aria-hidden="true"><div class="cover-art"></div><span>SUSSEX COLLEGE</span><strong>${e(item.category)}</strong><small>Pupil’s Book · Grade ${item.grade}</small></div></div>` : uniformArt(item.art)}<div class="stores-item-info"><small>${kind === "books" ? "Grade " + item.grade + " · 2027 demo edition" : "School collection · Sample sizes"}</small><h2>${e(item.title)}</h2><p>${kind === "books" ? "The school-issued pupil’s book for this subject." : "Choose a size before adding it to your reservation list."}</p><form data-form="store-add"><input type="hidden" name="kind" value="${kind}"><input type="hidden" name="itemId" value="${e(item.id)}"><div class="stores-item-fields"><label class="field">${kind === "books" ? "Edition" : "Size"}<select name="variantId" aria-label="${e(item.title)} ${kind === "books" ? "edition" : "size"}">${choices(variants.map((variant) => [variant.id, variant.label + (variant.available ? " · " + variant.available + " available" : " · Out of stock")]), variants.find((variant) => variant.available)?.id)}</select></label><label class="field">Quantity<select name="quantity">${choices((kind === "books" ? [1] : [1, 2, 3]).map((value) => [value, value]), 1)}</select></label></div>${available ? '<button class="button secondary" type="submit">' + icon("plus", 17) + 'Add to reservation list</button>' : badge("Currently unavailable", "amber")}${error}</form></div></article>`;
}
function requestCard(request, kind, staff = false) {
  return `<article class="surface stores-request-card"><header><div><small>${e(request.reference)} · ${dateLabel(request.createdAt)}</small><h3>${e(request.studentName)}</h3><p>${e(request.admission)} · Class ${e(request.className)}</p></div>${badge(reservationStatuses[request.status], statusTone(request.status))}</header><p>${request.items.map((line) => `${e(line.title)}${kind === "uniforms" ? " · Size " + e(line.variant) : ""} × ${line.quantity}`).join("<br>")}</p>${request.status === "ready" ? `<div class="stores-pickup"><strong>Ready at ${e(request.collection.location)}</strong><span>${e(request.collection.date)} · ${e(request.collection.window)}</span><span>Bring reference <strong>${e(request.reference)}</strong> and the pupil’s admission number.</span></div>` : request.status === "requested" ? '<p class="stores-hint">Awaiting the store’s stock confirmation. Collection details appear when ready.</p>' : ""}<div class="stores-actions">${button(staff ? "Review reservation" : "View reservation", "store-request", { value: kind + "|" + request.id, variant: "secondary", iconName: "file" })}${!staff && ["requested", "confirmed"].includes(request.status) ? button("Cancel request", "store-cancel", { value: kind + "|" + request.id, variant: "secondary" }) : ""}</div></article>`;
}
function parentPage(options, kind, scope) {
  const f = options.stores, items = storeCatalogue(options.state, options.context, kind, f), requests = storeReservations(options.state, options.context, kind, f), bag = reservationBag(options.state, options.context, kind);
  return `<section class="stores-parent">${pageHeading(storeKinds[kind].name, `Reserve for ${e(scope.child.name)} and collect from the school’s ${storeKinds[kind].store}.`, button(`Reservation list (${bag.reduce((sum, line) => sum + line.quantity, 0)})`, "store-bag", { value: kind, iconName: "bag" }))}
    <section class="stores-parent-banner ${kind === "uniforms" ? "uniform-banner" : ""}"><div>${badge("RESERVE & COLLECT", "green")}<h2>${kind === "books" ? "Pupil’s books for the school year" : "School uniform, ready for collection"}</h2><p>${kind === "books" ? `Grade ${scope.child.grade} · 2027 sample book list. No additional reading books are offered.` : "Select the required items, sizes and quantities. Sizes and uniform designs are illustrative."}</p><p>Send a reservation request. The store confirms stock and collection details.</p></div>${icon(kind === "books" ? "book" : "package", 58)}</section>
    <nav class="stores-local-tabs" aria-label="${storeKinds[kind].name} views">${tabButton("Browse " + (kind === "books" ? "pupil’s books" : "uniforms"), "catalogue", kind, f.tab === "catalogue")}${tabButton("My reservations", "reservations", kind, f.tab === "reservations")}</nav>
    <div class="stores-toolbar">${search(f, kind)}${f.tab === "reservations" ? statusFilter(f, kind) : ""}</div>
    ${f.tab === "catalogue" ? items.length ? `<div class="book-grid stores-item-grid">${items.map((item) => itemCard(options.state, item, kind)).join("")}</div>` : `<section class="surface">${emptyState("book", "No items available", kind === "books" ? "The Book Store has no matching pupil’s books for this grade yet." : "Try another search or check with the Uniform Store.")}</section>` : `<div class="stores-request-grid">${requests.map((request) => requestCard(request, kind)).join("") || `<section class="surface">${emptyState("package", "No reservations found", "Requests for the selected child will appear here.")}</section>`}</div>`}
    ${kind === "books" ? legacyRecords(options.state, options.context) : ""}</section>`;
}
function statusFilter(f, kind) {
  return `<label class="field stores-status">Reservation status<select data-change="store-status" data-kind="${kind}">${choices(Object.entries({ all: "All statuses", ...reservationStatuses }), f.status)}</select></label>`;
}
function legacyRecords(state, context) {
  const orders = (state.orders || []).filter((order) => order.branch === context.branch && order.parent === context.account.id);
  return orders.length ? `<details class="surface stores-legacy"><summary>Earlier family book records (${orders.length})</summary><p>Read-only records from the previous demo. They are not student reservations and have no payment or checkout action.</p>${orders.map((order) => `<article><strong>${e(order.number)}</strong><p>${order.items.map((line) => e(line.title) + " × " + line.quantity).join(", ") || "Earlier record"} · ${order.status === "collected" ? "Collected" : "Earlier request"}</p></article>`).join("")}</details>` : "";
}
function overview(options, kind) {
  const m = storeMetrics(options.state, options.context, kind);
  return `${pageHeading(storeKinds[kind].store + " overview", "Review reservations, prepare collections and keep school stock accurate.")}<div class="driver-metrics stores-metrics">${[["Awaiting review", m.pending, "clock"], ["Ready to collect", m.ready, "package"], ["Collected reservations", m.collected, "checkCircle"], ["Units held for collection", m.held, "bag"]].map(([label, value, name]) => `<article class="surface driver-metric">${icon(name, 20)}<strong>${value}</strong><span>${label}</span></article>`).join("")}</div><section class="stores-workflow"><strong>Request</strong><span>Store confirms stock</span><span>Ready at school counter</span><strong>Collected</strong></section><h2 class="stores-section-title">Latest requests</h2><div class="stores-request-grid">${m.requests.slice(0, 6).map((request) => requestCard(request, kind, true)).join("") || `<section class="surface">${emptyState("package", "No parent requests yet", "Reservations submitted through the Parent portal arrive in this school’s " + storeKinds[kind].store + ".")}</section>`}</div>`;
}
function catalogue(options, kind) {
  const { state, context } = options, f = options.stores, items = storeCatalogue(state, context, kind, f);
  return `${pageHeading(storeKinds[kind].store + " catalogue & stock", "Manage on-hand quantities and listing availability. Confirmed reservations hold stock.")}<div class="stores-toolbar">${search(f, kind)}${kind === "books" ? `<label class="field stores-status">Grade<select data-change="store-grade" data-kind="${kind}">${choices([["all", "All grades"], ...Array.from({ length: 13 }, (_, index) => [index + 1, "Grade " + (index + 1)])], f.grade)}</select></label>` : ""}</div><section class="surface"><div class="table-scroll"><table class="course-table" aria-label="${storeKinds[kind].store} stock"><thead><tr><th>Item</th><th>School</th><th>${kind === "books" ? "Edition" : "Size"}</th><th>On hand</th><th>Held</th><th>Available</th><th>Listing</th><th></th></tr></thead><tbody>${items.flatMap((item) => item.variants.map((variant) => {
    const stock = storeStock(state, item, variant);
    return `<tr><td><strong>${e(item.title)}</strong><div class="secondary-text">${kind === "books" ? "Grade " + item.grade : "Uniform"}</div></td><td>${e(state.branches.find((branch) => branch.id === item.branch)?.name)}</td><td>${e(variant.label)}</td><td>${stock.onHand}</td><td>${stock.held}</td><td>${stock.available}</td><td>${badge(item.enabled ? "Listed" : "Hidden", item.enabled ? "green" : "neutral")}</td><td>${button("Update stock", "store-stock", { value: kind + "|" + item.id + "|" + variant.id, variant: "secondary compact", iconName: "edit" })}</td></tr>`;
  })).join("") || '<tr><td colspan="8">No matching stock in this school.</td></tr>'}</tbody></table></div></section><p class="stores-hint">Sample catalogue only. Book lists, uniform designs, sizes and quantities must be confirmed by the school. No prices are configured.</p>`;
}
function requests(options, kind, collection = false) {
  const f = options.stores, rows = storeReservations(options.state, options.context, kind, f).filter((request) => !collection || ["ready", "collected"].includes(request.status));
  return `${pageHeading(collection ? "School collection counter" : "Parent reservation requests", collection ? "Verify the reference and record handover to the receiving adult." : "Each request is assigned to this school’s " + storeKinds[kind].store + ".")}<div class="stores-toolbar">${search(f, kind)}${statusFilter(f, kind)}</div><div class="stores-request-grid">${rows.map((request) => requestCard(request, kind, true)).join("") || `<section class="surface">${emptyState("package", "No matching reservations", collection ? "Mark a confirmed reservation Ready to collect before recording handover." : "Parent requests will appear here when submitted.")}</section>`}</div>`;
}
function reports(options, kind) {
  const f = options.stores, reports = storeReports(options.state, options.context, kind), selected = reports.find((report) => report.id === f.reportId) || reports[0];
  return `${pageHeading(storeKinds[kind].store + " reports", "Capture school/store snapshots. Reports omit private notes and receiving-adult details.")}<section class="surface stores-report-controls"><label class="field">Report type<select data-change="store-report-type" data-kind="${kind}">${choices(Object.entries(storeReportTypes), f.reportType)}</select></label>${button("Generate report", "store-report", { value: kind, iconName: "file" })}</section><section class="surface stores-report-result">${selected ? `<header><div><h2>${e(selected.title)}</h2><p>${dateLabel(selected.createdAt)} · ${selected.rows.length} rows</p></div>${button("Download CSV", "store-report-download", { value: kind + "|" + selected.id, iconName: "download", variant: "secondary" })}</header><div class="table-scroll"><table class="course-table"><thead><tr>${selected.headers.map((heading) => `<th>${e(heading)}</th>`).join("")}</tr></thead><tbody>${selected.rows.slice(0, 20).map((row) => `<tr>${row.map((value) => `<td>${e(value)}</td>`).join("")}</tr>`).join("")}</tbody></table></div><p class="stores-hint">Preview shows the first 20 rows; CSV contains all rows.</p>` : emptyState("file", "No reports generated", "Generate a snapshot of this store’s reservations or stock.")}<div class="stores-report-history">${reports.map((report) => button(e(report.title) + " · " + dateLabel(report.createdAt), "store-report-open", { value: kind + "|" + report.id, variant: report.id === selected?.id ? "primary" : "secondary" })).join("")}</div></section>`;
}
export function storePage(options, kind) {
  const scope = storesScope(options.state, options.context, kind);
  if (!scope) return emptyState("package", "No store access", "Choose a current student or appointed school store account.");
  if (scope.parent) return parentPage(options, kind, scope);
  const dedicated = ["librarian", "uniform_store"].includes(options.context.role), view = options.stores.view || "catalogue";
  return `<section class="chairman-portal section-portal stores-portal"><header class="driver-identity"><div><span class="eyebrow">${storeKinds[kind].store.toUpperCase()}</span><h1>${storeKinds[kind].store} workspace</h1><p>${e(scope.context.account.name)} · ${scope.branches.length === 1 ? e(scope.branches[0].school) : "Selected school scope"}</p></div>${badge("Reserve & collect", "green")}</header>${options.scopeControls || ""}<nav class="chairman-view-bar section-view-bar" aria-label="${storeKinds[kind].store} views">${storeViews.map((item) => dedicated ? `<a href="#${options.context.role}/overview/${item.id}" aria-label="${item.name}" ${view === item.id ? 'class="is-active" aria-current="page"' : ""}>${icon(item.icon, 18)}<span class="chairman-view-full">${item.name}</span><span class="chairman-view-short">${item.short}</span></a>` : tabButton(item.short, item.id, kind, view === item.id)).join("")}</nav><div class="chairman-analytics section-analytics">${({ summary: overview, catalogue, reservations: requests, collections: (options, kind) => requests(options, kind, true), reports })[view](options, kind)}</div></section>`;
}
export const booksPage = (options) => storePage(options, "books");
export const uniformsPage = (options) => storePage(options, "uniforms");
export function storeBagForm(state, context, kind) {
  const bag = reservationBag(state, context, kind), scope = storesScope(state, context, kind);
  return `<div class="form-body"><h3>${e(scope.child.name)} · ${e(scope.child.admissionNumber)}</h3><p>Request for ${storeKinds[kind].store}. Stock is held only after the store confirms your reservation.</p>${bag.map((line) => `<article class="stores-bag-row"><div><strong>${e(line.title)}</strong><p>${e(line.variant)} · Quantity ${line.quantity}</p>${line.invalid || line.available < line.quantity ? '<small class="stores-invalid">Unavailable — remove or review this item.</small>' : ""}</div>${button("Remove", "store-remove", { value: kind + "|" + line.itemId + "|" + line.variantId, variant: "secondary compact" })}</article>`).join("") || emptyState("bag", "Your reservation list is empty", "Choose an item from the pupil’s books or uniform section.")}<p class="stores-hint">Reservations are for school collection. No payment details are requested.</p></div>${bag.length ? `<footer class="dialog-footer">${button("Keep browsing", "close-dialog", { variant: "secondary" })}${button("Submit reservation", "store-submit", { value: kind, iconName: "checkCircle" })}</footer>` : ""}`;
}
export function storeRequestDetail(state, context, kind, id) {
  const request = storeReservations(state, context, kind).find((request) => request.id === id), scope = storesScope(state, context, kind);
  const transitions = ({ requested: [["confirmed", "Confirm stock"], ["declined", "Decline request"]], confirmed: [["ready", "Mark ready to collect"], ["cancelled", "Cancel reservation"]], ready: [["collected", "Record collection"], ["cancelled", "Cancel reservation"]] })[request.status] || [];
  return `<div class="form-body stores-request-detail">${badge(reservationStatuses[request.status], statusTone(request.status))}<h3>${e(request.reference)}</h3><p>${e(request.studentName)} · ${e(request.admission)} · Class ${e(request.className)}</p><p>Academic year ${e(request.academicYear)} · ${storeKinds[kind].store}</p><ul>${request.items.map((line) => `<li>${e(line.title)} · ${e(line.variant)} × ${line.quantity}</li>`).join("")}</ul>${request.collection ? `<div class="stores-pickup"><strong>${e(request.collection.location)}</strong><span>${e(request.collection.date)} · ${e(request.collection.window)}</span><span>Collection reference: ${e(request.reference)}</span></div>` : '<p>The store will set collection details when the reservation is ready.</p>'}${request.reason ? `<p><strong>Store update:</strong> ${e(request.reason)}</p>` : ""}${request.collected ? `<p>Collected by ${e(request.collected.receiver)} on ${dateLabel(request.collected.at)}.</p>` : ""}<h3>Reservation progress</h3><ol class="stores-history">${request.history.map((event) => `<li><strong>${reservationStatuses[event.status]}</strong><span>${dateLabel(event.at)}${!scope.parent ? " · " + e(event.by) : ""}</span></li>`).join("")}</ol>${!scope.parent ? `<h3>Internal store notes</h3>${request.internalNotes.map((note) => `<p>${e(note.text)}<small> · ${e(note.by)}</small></p>`).join("") || '<p>No internal notes.</p>'}` : ""}</div>${scope.canManage && transitions.length ? `<footer class="dialog-footer stores-actions">${transitions.map(([status, label]) => button(label, "store-process", { value: kind + "|" + id + "|" + status, variant: ["declined", "cancelled"].includes(status) ? "secondary" : "primary" })).join("")}</footer>` : ""}`;
}
export function storeProcessForm(state, context, kind, id, status) {
  const request = storeReservations(state, context, kind).find((request) => request.id === id);
  return `<form data-form="store-process"><div class="form-body"><input type="hidden" name="kind" value="${kind}"><input type="hidden" name="id" value="${e(id)}"><input type="hidden" name="status" value="${status}"><h3>${e(request.reference)} · ${e(request.studentName)}</h3><p>Set status: <strong>${reservationStatuses[status]}</strong></p>${status === "ready" ? `<label class="field">Collection date<input type="date" name="date" min="2026-11-22" max="2026-12-31" value="2026-11-23" required></label><label class="field">Counter / location<input name="location" value="${storeKinds[kind].store} counter" maxlength="100" required></label><label class="field">Collection hours<input name="window" placeholder="e.g. 8:00 AM – 2:00 PM" maxlength="80" required></label>` : ""}${status === "collected" ? `<p>Verify the reference and pupil’s admission number at handover.</p><label class="field">Reservation reference<input name="reference" placeholder="Enter parent’s reference" required></label><label class="field">Receiving adult’s name<input name="receiver" maxlength="80" required></label>` : ""}${["declined", "cancelled"].includes(status) ? '<label class="field">Reason shown to parent<textarea name="reason" maxlength="300" required rows="3"></textarea></label>' : ""}<label class="field">Internal store note (optional)<textarea name="note" maxlength="1000" rows="3"></textarea></label><p class="stores-hint">Internal notes are hidden from the Parent portal.</p>${error}</div>${footer(status === "confirmed" ? "Confirm and hold stock" : status === "ready" ? "Save collection details" : status === "collected" ? "Confirm collection" : "Save store decision")}</form>`;
}
export function storeStockForm(state, context, kind, id, variantId) {
  const item = storeCatalogue(state, context, kind).find((item) => item.id === id), variant = item.variants.find((variant) => variant.id === variantId), stock = storeStock(state, item, variant);
  return `<form data-form="store-stock"><div class="form-body"><input type="hidden" name="kind" value="${kind}"><input type="hidden" name="id" value="${e(id)}"><input type="hidden" name="variantId" value="${e(variantId)}"><h3>${e(item.title)} · ${e(variant.label)}</h3><p>${stock.held} held · ${stock.available} available</p><label class="field">On-hand units<input type="number" name="stock" min="${stock.held}" max="10000" value="${stock.onHand}" step="1" required></label><label class="roster-check"><input type="checkbox" name="enabled" ${item.enabled ? "checked" : ""}>List this item in the Parent portal (all sizes/editions)</label><label class="field">Adjustment reason<textarea name="note" rows="3" maxlength="500" required></textarea></label><p>On-hand stock cannot fall below units held for confirmed reservations. Hiding an item blocks new requests; existing confirmed requests can still be fulfilled.</p>${variant.changes?.length ? `<h3>Recent stock changes</h3>${variant.changes.slice(-3).reverse().map((change) => `<p>${change.before} → ${change.after} · ${e(change.note)}</p>`).join("")}` : ""}${error}</div>${footer("Save stock update")}</form>`;
}
